const out = [];
for (const item of $input.all()) {
  const json = item.json || {};
  const binary = item.binary || {};
  const attachments = [];
  for (const key of Object.keys(binary)) {
    if (key === 'mime') continue;
    const b = binary[key];
    if (b && b.fileName) {
      attachments.push({ name: b.fileName, mimeType: b.mimeType || 'unknown', size: b.fileSize || 0 });
    }
  }
  let bodyText = '';
  try {
    const bodyRaw = (json.body && json.body.content) || json.bodyPreview || '';
    bodyText = (typeof bodyRaw === 'string')
      ? bodyRaw.replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim()
      : '';
  } catch (e) { bodyText = ''; }
  const headers = [];
  try {
    if (binary.mime && binary.mime.data) {
      const mime = Buffer.from(binary.mime.data, 'base64').toString('utf8');
      const lines = mime.split(/\r?\n/);
      const h = [];
      for (const line of lines) {
        if (line.trim() === '') break;
        if (line.includes(':')) {
          const idx = line.indexOf(':');
          h.push({ name: line.slice(0, idx).trim(), value: line.slice(idx + 1).trim() });
        }
      }
      const want = ['Return-Path', 'From', 'Reply-To', 'Subject', 'Delivered-To', 'Received', 'Authentication-Results', 'X-Originating-IP', 'X-Sender-IP', 'Message-ID', 'X-Spam-Score', 'DKIM-Signature'];
      for (const n of want) {
        for (const f of h.filter(x => x.name === n).slice(0, 2)) {
          headers.push(f.name + ': ' + f.value);
        }
      }
    }
  } catch (e) { /* cabeceras opcionales */ }
  const fromAddr = (json.from && json.from.emailAddress) ? json.from.emailAddress.address : '';
  const fromName = (json.from && json.from.emailAddress && json.from.emailAddress.name) ? json.from.emailAddress.name : '';
  const toAddresses = (json.toRecipients || []).map(r => (r.emailAddress && r.emailAddress.address) || '').filter(Boolean).join('; ');
  out.push({ json: {
    id: json.id,
    internetMessageId: json.internetMessageId,
    subject: json.subject,
    fromName: fromName,
    fromEmail: fromAddr,
    toAddresses: toAddresses,
    receivedDateTime: json.receivedDateTime,
    bodyText: bodyText.slice(0, 6000),
    headers: headers,
    attachments: attachments
  }});
}
return out;

const out = [];
const model = process.env.N8N_OLLAMA_MODEL || 'qwen3.5:latest';
const ollamaUrl = process.env.N8N_OLLAMA_URL || 'http://127.0.0.1:11434/api/chat';
const systemPrompt = 'Eres un analista senior de ciberseguridad experto en email. Clasifica el correo y devuelve SOLO un JSON con este esquema exacto: {"verdict":"malicious|phishing|spam|benign","confidence":0-100,"risk_level":"low|medium|high|critical","summary":"resumen en espanol de 1-2 frases","reasons":["hallazgo1","hallazgo2"]}. Evalua: suplantacion del remitente/dominio, urgimiento y presion, peticiones de pagos/claves/credenciales, enlaces sospechosos, adjuntos con doble extension, Reply-To distinto al From, autenticacion SPF/DKIM/DMARC de las cabeceras. No marques falsos positivos sin evidencia concreta.';
for (const item of $input.all()) {
  const d = item.json;
  const headerBlock = (d.headers || []).join('\n');
  const attachBlock = ((d.attachments || []).map(a => '  - ' + a.name + ' (' + a.mimeType + ', ' + (a.size || 0) + ' B)')).join('\n') || '  (sin adjuntos)';
  const userContent = ['SUBJECT: ' + (d.subject || ''), 'FROM: ' + (d.fromName || '') + (d.fromEmail ? ' <' + d.fromEmail + '>' : ''), 'TO: ' + (d.toAddresses || ''), 'RECEIVED: ' + (d.receivedDateTime || ''), '', 'HEADERS:', headerBlock || '  (no disponible)', '', 'BODY:', (d.bodyText || '').slice(0, 5000), '', 'ATTACHMENTS:', attachBlock].join('\n');
  let parsed = null;
  let raw = '';
  try {
    const payload = { model: model, format: 'json', stream: false, think: false, options: { temperature: 0, num_predict: 400 }, messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userContent }] };
    const resp = await this.helpers.httpRequest({ method: 'POST', url: ollamaUrl, json: true, headers: { 'Content-Type': 'application/json' }, body: payload });
    raw = resp && resp.message ? resp.message.content : '';
    const s = raw.indexOf('{');
    const e = raw.lastIndexOf('}');
    if (s >= 0 && e > s) parsed = JSON.parse(raw.slice(s, e + 1));
  } catch (err) {
    parsed = { verdict: 'error', confidence: 0, risk_level: 'unknown', summary: 'Error de Ollama: ' + (err.message || err), reasons: [] };
  }
  const verdict = String((parsed && parsed.verdict) || 'unknown').toLowerCase();
  const risk = String((parsed && parsed.risk_level) || 'unknown').toLowerCase();
  const confidence = Number((parsed && parsed.confidence) || 0);
  const isThreat = ['phishing', 'malicious'].includes(verdict) || ['high', 'critical'].includes(risk);
  const reasons = (parsed && Array.isArray(parsed.reasons) ? parsed.reasons : []).map(String);
  const summary = (parsed && parsed.summary) || 'Sin resultado';
  const attachInfo = ((d.attachments || []).map(a => a.name)).join(', ') || 'ninguno';
  const replyTo = (d.toAddresses || d.fromEmail || '').split(';').map(s => s.trim()).filter(Boolean).join(',');
  const replySubject = 'RE: [' + verdict.toUpperCase() + '] Analisis - ' + (d.subject || 'correo');
  const lines = [];
  lines.push('Analisis automatico de seguridad del correo recibido.');
  lines.push('');
  lines.push('Veredicto: ' + verdict.toUpperCase());
  lines.push('Riesgo: ' + risk + '  |  Confianza: ' + confidence + '%');
  lines.push('');
  lines.push('Resumen: ' + summary);
  if (reasons.length) { lines.push(''); lines.push('Motivos:'); for (const r of reasons) lines.push(' - ' + r); }
  lines.push('');
  lines.push('Remitente: ' + (d.fromName || '') + (d.fromEmail ? ' <' + d.fromEmail + '>' : ''));
  lines.push('Destinatario(s): ' + d.toAddresses);
  lines.push('Adjuntos: ' + attachInfo);
  lines.push('');
  if (isThreat) {
    lines.push('ATENCION: se detecto una posible amenaza. NO abra enlaces ni adjuntos. Notifique a su equipo de TI y elimine el correo.');
  } else {
    lines.push('No se detectaron senales claras de amenaza. Proceda con normalidad, manteniendo su personal.');
  }
  out.push({ json: { ...d, verdict: verdict, risk_level: risk, confidence: confidence, summary: summary, reasons: reasons, isThreat: isThreat, rawResult: raw.slice(0, 1500), replyTo: replyTo, replySubject: replySubject, replyBody: lines.join('\n') } });
}
return out;
